head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = "";

// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_11.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 조회조건 기업코드

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_RelcomMutlTrd_OnLoadError
 * @description dts_RelcomMutlTrd 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_RelcomMutlTrd_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_RelcomMutlTrd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_11.dts_RelcomMutlTrd_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_RelcomMutlTrd_OnLoadCompleted
 * @description dts_RelcomMutlTrd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_RelcomMutlTrd_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_RelcomMutlTrd.errorMsg) {
            await $c.win.alert(dts_RelcomMutlTrd.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_11.dts_RelcomMutlTrd_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_RelcomMutlTrd_OnDblClick
 * @description grd_RelcomMutlTrd 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_RelcomMutlTrd_OnDblClick = async function(row, colid) {
    try {
        if (colid === "BAS_YYMM") {
            // 담보및보증내역 상세  팝업 오픈
            await scwin.relcomMutlTrdDtlSrchOpen(row);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_11.grd_RelcomMutlTrd_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 담보및지급보증 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_RelcomMutlTrd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_RelcomMutlTrd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_RelcomMutlTrd.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    if (scwin.vKisCd === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name relcomMutlTrdDtlSrchOpen
 * @description 담보및지급보증 상세 팝업
 * @param {*} pRow pRow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.relcomMutlTrdDtlSrchOpen = async function(pRow) {
    fn_GetPar = scwin.getParKey;
    const options = {
        id: "ULDFIS00300_P7",
        title: "담보및보증내역 검색",
        type: "browserPopup",
        width: 850 + 20,
        height: 840 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00300_P7.gfm", options);
};

/**
 * @method
 * @name getParKey
 * @description RETI_PAY_ALWNC_DTL 팝업으로 값을 넘김.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParKey = function(arrPar) {
    const nRow = dts_RelcomMutlTrd.getRowPosition();
    arrPar[0] = dts_RelcomMutlTrd.getCellData(nRow, "COM_CD");
    arrPar[1] = dts_RelcomMutlTrd.getCellData(nRow, "BAS_YYMM");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDownload = async function() {
    if (dts_RelcomMutlTrd.getRowCount() <= 0) {
        await $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_RelcomMutlTrd, {fileName: "담보및지급보증", type: "8"});
};
